package com.italiano2774.nativeapp;
import android.os.Bundle;import android.text.*;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.recyclerview.widget.*;import java.util.*;
public class PhraseFragment extends Fragment{
 private PhraseRepository repo;private PhraseAdapter adapter;private AudioPlayer audio;private ProgressStore progress;private EditText search;private Spinner category;private TextView stats;
 @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){View v=i.inflate(R.layout.fragment_phrases,c,false);repo=PhraseRepository.get(requireContext());progress=new ProgressStore(requireContext());audio=new AudioPlayer(requireContext(),progress);search=v.findViewById(R.id.edit_phrase_search);category=v.findViewById(R.id.spinner_phrase_category);stats=v.findViewById(R.id.text_phrase_stats);RecyclerView rv=v.findViewById(R.id.recycler_phrases);rv.setLayoutManager(new LinearLayoutManager(requireContext()));adapter=new PhraseAdapter(new PhraseAdapter.Listener(){public void speak(Phrase p){audio.speak(p.italian,0.92f);}public void reviewed(Phrase p){progress.recordAuxiliaryResult("phrases",true,0);SentenceFsrsRepository.record(requireContext(),"高频短语",p.italian,p.chinese,true,null);Toast.makeText(requireContext(),"已复习，并进入句子长期记忆",Toast.LENGTH_SHORT).show();}});rv.setAdapter(adapter);List<String> cats=new ArrayList<>();cats.add("全部");cats.addAll(repo.categories());ArrayAdapter<String> sa=new ArrayAdapter<>(requireContext(),R.layout.item_spinner_text,cats);sa.setDropDownViewResource(R.layout.item_spinner_dropdown);category.setAdapter(sa);category.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onItemSelected(AdapterView<?> p,View v,int pos,long id){refresh();}public void onNothingSelected(AdapterView<?> p){}});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int b,int c){refresh();}public void afterTextChanged(Editable e){}});refresh();return v;}
 private void refresh(){String cat=category.getSelectedItem()==null?"全部":category.getSelectedItem().toString();List<Phrase> x=repo.filter(search.getText()==null?"":search.getText().toString(),cat);adapter.submit(x);stats.setText("高频词块 "+repo.all().size()+" 条 · 当前显示 "+x.size()+" 条 · 已复习 "+progress.auxiliaryAttempts("phrases")+" 次");}
 @Override public void onDestroyView(){if(audio!=null)audio.release();super.onDestroyView();}
}
